const worlds=[{name:'Skyline Drift',maker:'Nova Studio',players:'2.4K',visits:'18.2M',className:'drift',tag:'RACING',description:'Build your ride, race the clouds, and drift through a neon skyway with your crew.'},{name:'Pocket Quest',maker:'Moss & Co.',players:'1.1K',visits:'9.8M',className:'quest',tag:'ADVENTURE',description:'A cozy shared quest where every cave, creature, and treasure has a story.'},{name:'Circuit Breakers',maker:'Unit 9',players:'874',visits:'4.2M',className:'circuit',tag:'ACTION',description:'Team up in a fast, friendly arena built for five-minute rounds and big comebacks.'},{name:'Tiny Cabin Club',maker:'Luna Made',players:'646',visits:'2.1M',className:'cabin',tag:'SOCIAL',description:'Decorate your cabin, meet new people, and host an evening by the fire.'}];
const friends=[{name:'MikaMakes',initials:'MM'},{name:'pixelpup',initials:'PP'},{name:'Eli',initials:'EL'},{name:'SoraBuilds',initials:'SB'}],grid=document.querySelector('#world-grid');
grid.innerHTML=worlds.map((w,i)=>`<article class="card" data-world="${i}" tabindex="0" role="button"><div class="cover ${w.className}"><span class="label">${w.tag}</span><i class="shape"></i></div><div class="card-info"><div class="card-title">${w.name}</div><div class="byline">by ${w.maker}</div><div class="meta"><span>● ${w.players} playing</span><span>${w.visits} visits</span></div></div></article>`).join('');
document.querySelector('#friend-list').innerHTML=friends.map((f,i)=>`<article class="friend"><span class="avatar" style="background:linear-gradient(135deg,hsl(${210+i*43},45%,42%),hsl(${32+i*29},85%,63%))">${f.initials}</span><span><strong>${f.name}</strong><small>In ${worlds[i].name}</small></span></article>`).join('');
const dialog=document.querySelector('#world-dialog'),content=document.querySelector('#dialog-content'),slug=v=>v.toLowerCase().replace(/[^a-z0-9]+/g,'-').replace(/(^-|-$)/g,'');
function openWorld(i){const w=worlds[i];content.innerHTML=`<div class="dialog-body"><p class="eyebrow">${w.tag} · by ${w.maker}</p><h2>${w.name}</h2><p>${w.description}</p><div class="dialog-stats"><span><strong>${w.players}</strong>playing now</span><span><strong>${w.visits}</strong>all-time visits</span></div><button class="button primary" id="play">Play with friends →</button></div>`;dialog.showModal();document.querySelector('#play').onclick=()=>{dialog.close();enterRoom(slug(w.name),w.name)}}
grid.onclick=e=>{const c=e.target.closest('.card');if(c)openWorld(c.dataset.world)};grid.onkeydown=e=>{if(e.key==='Enter')openWorld(e.target.dataset.world)};document.querySelector('.close').onclick=()=>dialog.close();document.querySelector('#surprise').onclick=()=>openWorld(Math.floor(Math.random()*worlds.length));document.querySelector('#new-world').onclick=()=>{const name=prompt('Name your new shared room:','My first Orbit room');if(name?.trim())enterRoom(slug(name).slice(0,36),name.trim())};document.querySelector('#open-projects').onclick=()=>toast('Your project dashboard will appear after sign-in is connected.');document.querySelector('#add-friend').onclick=()=>toast('Friend requests are next after the shared-room loop.');
let toastTimer;function toast(msg){const e=document.querySelector('#toast');e.textContent=msg;e.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>e.classList.remove('show'),3500)}
const canvas=document.querySelector('#world-canvas'),ctx=canvas.getContext('2d'),game=document.querySelector('#game'),shell=document.querySelector('.shell');let socket,roomName,selfId,players={},keys=new Set(),lastSent=0;const myName=localStorage.orbitName||(()=>{const n=prompt('Choose a display name for Orbit:','CreatorJay')?.trim().slice(0,18)||'Guest';localStorage.orbitName=n;return n})();
function enterRoom(code,title){roomName=code;document.querySelector('#room-title').textContent=title;document.querySelector('#room-code').textContent=`room / ${code}`;shell.hidden=true;game.hidden=false;connect()}function connect(){socket?.close();socket=new WebSocket(`${location.protocol==='https:'?'wss':'ws'}://${location.host}/ws`);socket.onopen=()=>socket.send(JSON.stringify({type:'join',room:roomName,name:myName}));socket.onmessage=e=>receive(JSON.parse(e.data));socket.onclose=()=>{if(!game.hidden)toast('Connection lost. Rejoin the room to try again.')}}
function receive(m){if(m.type==='state'){selfId=m.selfId;players=m.players;updatePlayers()}if(m.type==='players'){players=m.players;updatePlayers()}if(m.type==='chat')addChat(m)}function updatePlayers(){document.querySelector('#players-list').innerHTML=Object.values(players).map(p=>`<div class="player-row"><span class="avatar" style="background:${p.color}">${p.name.slice(0,2).toUpperCase()}</span>${safe(p.name)}${p.id===selfId?' (you)':''}</div>`).join('')}function addChat(m){const n=document.createElement('div');n.className='message';n.innerHTML=`<b>${safe(m.name)}</b> ${safe(m.text)}`;const l=document.querySelector('#chat-log');l.append(n);l.scrollTop=l.scrollHeight}function safe(v){return v.replace(/[&<>'"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[c]))}
document.querySelector('#chat-form').onsubmit=e=>{e.preventDefault();const i=document.querySelector('#chat-input'),text=i.value.trim();if(text&&socket?.readyState===1){socket.send(JSON.stringify({type:'chat',text}));i.value=''}};document.querySelector('#leave-game').onclick=()=>{socket?.close();game.hidden=true;shell.hidden=false};document.querySelector('#copy-invite').onclick=async()=>{const link=`${location.origin}${location.pathname}?room=${encodeURIComponent(roomName)}`;try{await navigator.clipboard.writeText(link);toast('Invite link copied. Open it in another tab to play together.')}catch{toast(`Share this room code: ${roomName}`)}};
addEventListener('keydown',e=>{if(['ArrowUp','ArrowDown','ArrowLeft','ArrowRight','w','a','s','d','W','A','S','D'].includes(e.key)&&!game.hidden){keys.add(e.key.toLowerCase());e.preventDefault()}});addEventListener('keyup',e=>keys.delete(e.key.toLowerCase()));
function tick(t){if(!game.hidden&&selfId&&players[selfId]){const p=players[selfId],dx=(keys.has('arrowright')||keys.has('d')?1:0)-(keys.has('arrowleft')||keys.has('a')?1:0),dy=(keys.has('arrowdown')||keys.has('s')?1:0)-(keys.has('arrowup')||keys.has('w')?1:0);if(dx||dy){const d=Math.hypot(dx,dy);p.x=Math.max(30,Math.min(930,p.x+dx/d*2.8));p.y=Math.max(40,Math.min(550,p.y+dy/d*2.8));if(t-lastSent>45&&socket?.readyState===1){socket.send(JSON.stringify({type:'move',x:p.x,y:p.y}));lastSent=t}}draw()}requestAnimationFrame(tick)}function draw(){ctx.clearRect(0,0,960,600);ctx.fillStyle='#bde5e4';ctx.fillRect(0,0,960,600);ctx.fillStyle='#94cf8a';ctx.beginPath();ctx.ellipse(475,340,460,250,0,0,Math.PI*2);ctx.fill();ctx.fillStyle='#7bb978';ctx.beginPath();ctx.ellipse(490,357,270,135,0,0,Math.PI*2);ctx.fill();ctx.fillStyle='#f7d66b';ctx.beginPath();ctx.arc(835,88,42,0,Math.PI*2);ctx.fill();[['#4a7954',140,190,58],['#3d6c49',760,250,76],['#517e55',280,470,58]].forEach(([c,x,y,r])=>{ctx.fillStyle=c;ctx.beginPath();ctx.arc(x,y,r,0,Math.PI*2);ctx.fill()});Object.values(players).forEach(p=>{ctx.fillStyle='rgba(16,24,40,.16)';ctx.beginPath();ctx.ellipse(p.x,p.y+18,20,7,0,0,Math.PI*2);ctx.fill();ctx.fillStyle=p.color;ctx.beginPath();ctx.arc(p.x,p.y,17,0,Math.PI*2);ctx.fill();ctx.fillStyle='#fff';ctx.font='700 12px Manrope';ctx.textAlign='center';ctx.fillText(p.name,p.x,p.y-29)})}
const inviteRoom=new URLSearchParams(location.search).get('room');if(inviteRoom)enterRoom(inviteRoom,inviteRoom.replace(/-/g,' '));requestAnimationFrame(tick);
